def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 42.0))

    prev_bids = []
    urgent_score = 0.0
    rich_pressure = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
        opp_hp = opp.get('hp', 10)
        opp_nw = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0.0)
        if opp_nw >= 1 or opp_hp <= 4:
            urgent_score += 1.0
        if opp_budget >= 500:
            rich_pressure += 1.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # In this scenario supply 15-25 means at most one player gets full water (req=13).
    # So win probability depends on outbidding the strongest current rival without overspending.
    if hp <= 2 or no_water >= 2:
        bid = max(78.0, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        bid = max(62.0, avg_prev + 4.0)
    else:
        if highest_prev >= 110:
            bid = 36.0
        elif highest_prev >= 90:
            bid = 44.0
        elif highest_prev >= 70:
            bid = 52.0
        else:
            bid = 48.0

    # Slightly raise under stronger scarcity/pressure signals.
    if supply <= 16:
        bid += 8.0
    elif supply <= 19:
        bid += 4.0

    bid += urgent_score * 3.0
    bid += rich_pressure * 2.0

    # Early days preserve budget; late days convert budget into survival.
    if day <= 2 and hp >= 6:
        bid -= 6.0
    if day >= 8:
        bid += 6.0

    # Budget discipline.
    cap = budget
    if hp >= 6 and no_water == 0:
        cap = min(cap, DAILY_SALARY * 0.95)
    elif hp >= 4:
        cap = min(cap, DAILY_SALARY * 1.15)

    if budget < 40:
        bid = max(bid, budget * 0.85)

    bid = max(1.0, min(bid, cap))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid low but ensure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Desperation mode: If HP is very low, bid aggressively to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # If there were previous bids, react to the highest
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If yesterday's highest bid was very high (indicating strong competition)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If my HP is still good, I can be slightly less aggressive but still competitive
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.7)
            # If my HP is getting low, I need to be aggressive to secure water
            return min(my_status['budget'], DAILY_SALARY * 0.9)

        # If yesterday's highest bid was moderate, try to outbid slightly
        return min(my_status['budget'], max(DAILY_SALARY * 0.65, highest_prev_bid + 2.5))

    # Fallback if no yesterday bids (e.g., first day of meta-round)
    # Bid a solid amount to secure water without overspending
    return min(my_status['budget'], DAILY_SALARY * 0.75)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace')
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    supply = day_context['supply']
    day = day_context['day']
    if budget <= 0:
        return 0.0
    if hp <= 2 or no_water_days >= 2:
        target = min(budget, DAILY_SALARY * 1.0)
        if yesterday_bids:
            max_prev = max(yesterday_bids)
            target = max(target, max_prev + 1.0)
        return min(budget, target)
    if len(yesterday_bids) > 0:
        max_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        if max_prev >= DAILY_SALARY * 0.85:
            target = min(budget, DAILY_SALARY * 0.5)
            return target
        else:
            target = max(avg_prev + 2.0, DAILY_SALARY * 0.4)
            target = min(target, budget)
            return target
    else:
        if supply < WATER_REQ:
            return min(budget, DAILY_SALARY * 0.7)
        else:
            return min(budget, DAILY_SALARY * 0.5)
